InputFrame key(InputAction a=InputAction::Confirm){InputFrame f;f.buttons[static_cast<int>(a)].pressed=true;return f;}
template<class F>void rejects(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}need(failed,"Invalid presentation accepted");}
std::string read(const char* p){std::ifstream f(p);return {std::istreambuf_iterator<char>(f),{}};}
std::optional<Direction> next(const ExplorationScene& world,TilePosition goal){
 auto start=world.player().motion.tile();std::queue<TilePosition> q;q.push(start);std::map<std::pair<int,int>,std::optional<Direction>> first;first[{start.x,start.y}]={};
 while(!q.empty()){auto at=q.front();q.pop();if(at==goal){return first.at({at.x,at.y});}for(auto d:{Direction::Up,Direction::Right,Direction::Down,Direction::Left}){auto p=world.player();p.motion=CharacterMotion(at,d,p.motion.speed());auto tile=adjacentTile(at,d);auto cell=std::pair{tile.x,tile.y};if(first.contains(cell)||!world.canMove(p,d)){continue;}first[cell]=first.at({at.x,at.y}).value_or(d);q.push(tile);}}
 return {};
}
